import JSZip from "jszip";
import { describe, expect, it } from "vitest";
import { repairOdtImages } from "./odt-image-repair.js";
const PNG_BYTES = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13]);
async function buildOdtWithImage() {
    const zip = new JSZip();
    zip.file("mimetype", "application/vnd.oasis.opendocument.text");
    zip.file("content.xml", `<?xml version="1.0" encoding="UTF-8"?>
<office:document-content xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0"
  xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0"
  xmlns:draw="urn:oasis:names:tc:opendocument:xmlns:drawing:1.0"
  xmlns:xlink="http://www.w3.org/1999/xlink">
  <office:body><office:text>
    <text:p>
      <draw:frame>
        <draw:image xlink:href="Pictures/photo.png"/>
      </draw:frame>
    </text:p>
  </office:text></office:body>
</office:document-content>`);
    zip.file("Pictures/photo.png", PNG_BYTES);
    return zip.generateAsync({ type: "arraybuffer" });
}
describe("repairOdtImages", () => {
    it("replaces broken filename-only img src with embedded media data URL", async () => {
        const buffer = await buildOdtWithImage();
        const body = globalThis.document.createElement("div");
        body.innerHTML =
            '<div class="image-container"><img src="photo.png" alt="test"><div class="caption">photo.png</div></div>';
        await repairOdtImages(buffer, body);
        const img = body.querySelector("img");
        expect(img?.getAttribute("src")).toMatch(/^data:image\/png;base64,/);
    });
});
